def publish_(
    ctx, sdist=True, wheel=True, sign=False, dry_run=False, index=None
):
    """
    Wraps invocations.packaging.publish to add baked-in docs folder.
    """
    # Add the docs folder to the package
    docs_dir = os.path.join(ctx.root, 'docs')
    if os.path.exists(docs_dir):
        ctx.run(f'cp -r {docs_dir} dist/')

    # Publish the package
    args = []
    if sdist:
        args.append('--format=sdist')
    if wheel:
        args.append('--format=wheel')
    if sign:
        args.append('--sign')
    if index:
        args.append(f'--index-url={index}')

    publish.publish(
        ctx.root,
        dry_run=dry_run,
        *args
    )

def publish_(
    ctx, sdist=True, wheel=True, sign=False, dry_run=False, index=None
):
    """
    Wraps invocations.packaging.publish to add baked-in docs folder.
    """
    docs_path = 'docs'
    if not os.path.exists(docs_path):
        raise FileNotFoundError("Docs folder not found")

    with ctx.cd('.'):
        if dry_run:
            ctx.run('echo "Dry run: Would publish package with docs"')
        else:
            ctx.run('python setup.py sdist bdist_wheel')
            shutil.copytree(docs_path, 'dist/docs')
            ctx.run(f'python -m twine upload {"--sign" if sign else ""} {"--repository" + index if index else ""} dist/*' if not dry_run else 'echo "Dry run: Would upload package"')

def publish_(
    ctx, sdist=True, wheel=True, sign=False, dry_run=False, index=None
):
    """
    Wraps invocations.packaging.publish to add baked-in docs folder.
    """
    # Add baked-in docs folder to the files to be published
    ctx.files.extend(ctx.baked_files("docs"))
    # Invoke the original publish function
    return packaging.publish.publish(ctx, sdist=sdist, wheel=wheel, sign=sign, dry_run=dry_run, index=index)
